$ErrorActionPreference='Stop'
$tasks=@(Get-ScheduledTask | Where-Object {$_.TaskName -in @('DevResults site','VibeResults dev','DevResults e2e nightly')} | ForEach-Object {@{name=$_.TaskName;state=[string]$_.State;actions=@($_.Actions|ForEach-Object{@{execute=$_.Execute;arguments=$_.Arguments}})}})
$ports=@(443,9443,20415,20417,20418,20419,20615,20617,20618,20619,21415,21417,21418,21419)
$listeners=@(Get-NetTCPConnection -State Listen|Where-Object LocalPort -in $ports|Sort-Object LocalPort,OwningProcess|ForEach-Object{@{port=$_.LocalPort;pid=$_.OwningProcess}})
$processes=@(Get-CimInstance Win32_Process|Where-Object {$_.Name -in @('iisexpress.exe','node.exe') -and $_.CommandLine -and $_.CommandLine -notlike '*DevResultsEnvironments*'}|ForEach-Object{@{pid=$_.ProcessId;name=$_.Name;created=$_.CreationDate.ToUniversalTime().ToString('o')}})
$files=@('C:\Users\herb\setup\mini-migration.md','C:\Users\herb\setup\start-site.ps1','C:\Users\herb\setup\viberesults-reinstall.ps1','C:\Users\herb\setup\start-viberesults-dev.ps1','C:\Code\DevResults\devresults\DevResults\Web.config','C:\Code\DevResults\devresults\DevResults\SecureSettings.config','C:\Code\DevResults\devresults\.vs\DevResults\config\applicationhost.config','C:\Code\DevResults\devresults\.env.local')|ForEach-Object{if(Test-Path $_){@{path=$_;sha256=(Get-FileHash $_ -Algorithm SHA256).Hash}}}
$connection=[Data.SqlClient.SqlConnection]::new('Server=.;Integrated Security=true;Initial Catalog=master;Encrypt=false;Pooling=false')
try{$connection.Open();$command=$connection.CreateCommand();$command.CommandText="SELECT name,state_desc,create_date FROM sys.databases WHERE name NOT LIKE 'drenv[_]%' ORDER BY name";$reader=$command.ExecuteReader();$catalogs=@(while($reader.Read()){@{name=$reader.GetString(0);state=$reader.GetString(1);created=$reader.GetDateTime(2).ToString('o')}});$reader.Close()}finally{$connection.Dispose()}
@{capturedAt=[datetime]::UtcNow.ToString('o');tasks=$tasks;listeners=$listeners;processes=$processes;files=$files;catalogs=$catalogs}|ConvertTo-Json -Depth 20
